/**
 * Validates a port value and returns it as an integer.
 *
 * Accepts both numbers (already parsed by the CLI) and strings (from env vars).
 * Placeholder strings such as `$PORT`, empty/whitespace-only strings, and
 * out-of-range values are rejected. The error message keeps the offending value
 * quoted for strings and unquoted for numbers so it is clear where the value
 * originated.
 */
function validatePort(value: string | number): number {
  const display = typeof value === 'string' ? `"${value}"` : `${value}`;
  const invalid = (): never => {
    throw new Error(
      `Invalid value at port. Port must be a valid number from 1 to 65535, received ${display}.`
    );
  };

  let port: number;
  if (typeof value === 'number') {
    port = value;
  } else {
    const trimmed = value.trim();
    // Only accept plain digit strings. This rejects empty/whitespace-only
    // strings and unexpanded placeholders like `$PORT`.
    if (!/^\d+$/.test(trimmed)) {
      invalid();
    }
    port = Number(trimmed);
  }

  if (!Number.isInteger(port) || port < 1 || port > 65535) {
    invalid();
  }

  return port;
}

