  const claudePreview = isClaudePreviewLaunch(env);

  const resolved: DevCliOptions = { ...cliOptions };

  // Truthy env values take precedence over CLI-provided values.
  if (env.CI) {
    resolved.ci = env.CI;
  }
  if (env.SBCONFIG_CONFIG_DIR) {
    resolved.configDir = env.SBCONFIG_CONFIG_DIR;
  }
  if (env.SBCONFIG_HOSTNAME) {
    resolved.host = env.SBCONFIG_HOSTNAME;
